// VENDORED ASSET — DO NOT EDIT BY HAND.
// Browser build of the @query-farm/vgi client, authored in
// vgi-web-frontend (`bun run build:landing-client`). The shared landing
// page imports it from {prefix}/vgi-client.js to read catalog metadata
// over the VGI protocol. Base64-embedded so it survives single-file
// bundling (bun build) unchanged and is served as raw bytes.
// Regenerate with scripts/vendor-client-bundle.mjs.

const CLIENT_BUNDLE_B64 =
  "";

function decodeBase64(b64: string): Uint8Array {
  // atob is available on Node >=16, Bun, Deno, and workerd.
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

/** The vendored VGI browser client bundle, decoded to its raw bytes. */
export const CLIENT_BUNDLE_BYTES: Uint8Array = decodeBase64(CLIENT_BUNDLE_B64);
